function readRoute(){const p=new URLSearchParams((location.hash||'').replace(/^#/,'')),i=cities.findIndex(c=>c[0].toLowerCase()===(p.get('city')||'').toLowerCase());if(i>=0)selected=i;else if(!p.has('city')){const home=cities.findIndex(c=>c[0]===window.HomeCity?.get?.());if(home>=0)selected=home}const day=expectedDays().indexOf(p.get('day'));if(day>=0)selectedDay=day;if(p.has('hour'))selectedHour=Math.max(0,Math.min(23,Math.trunc(Number(p.get('hour'))||0)));const s=p.get('scenario');if(['live','heavy-rain','river-rise','blocked-drains'].includes(s))scenario=s;const tool=Object.hasOwn(MANAGER_TOOLS,p.get('tool'))?MANAGER_TOOLS[p.get('tool')]:'';dashboardView=p.get('view')==='mayor'||(tool&&p.get('view')!=='public')?'mayor':'public';managerTool=dashboardView==='mayor'?tool:''}
