function updateDashboardView(){const mayor=dashboardView==='mayor';document.body.classList.toggle('mayor-view',mayor);if($('mayor-panel'))$('mayor-panel').hidden=!mayor||!!managerTool;if($('manager-tool-bar'))$('manager-tool-bar').hidden=!mayor||!managerTool;for(const id of Object.values(MANAGER_TOOLS))$(id)?.classList.toggle('mayor-active-tool',mayor&&id===managerTool);$('manager-map-workspace')?.classList.toggle('mayor-active-tool',mayor&&managerTool==='map-panel');document.querySelectorAll('[data-manager-tool], [data-dashboard-view]').forEach(link=>{const tab=mayor?'':window.SiteTabs?.current||'',active=link.dataset.dashboardView?link.dataset.dashboardView===dashboardView&&!managerTool&&(!tab||tab==='overview'):mayor?MANAGER_TOOLS[link.dataset.managerTool]===managerTool:!!tab&&link.dataset.managerTool===tab;if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});document.title=mayor?'Mayor dashboard | El Nino Watch':'El Nino Watch | All 30 cities';const labels={'map-panel':'Flood map','daily-panel':'Detailed weather','alerts-panel':'Alerts','community-panel':'Reports'};if($('manager-tool-title'))$('manager-tool-title').textContent=`${cities[selected][0]} · ${labels[managerTool]||'Mayor dashboard'}`;const skip=$('skip-link');if(skip){skip.setAttribute('href',mayor?(managerTool?'#'+managerTool:'#mayor-panel'):'#watchlist');skip.textContent=mayor?(managerTool?'Skip to '+labels[managerTool]:'Skip to mayor dashboard'):'Skip to 30-city watchlist'}}
