async function loadManagerReports(i,force=false){if(!cities[i]||!window.CityManager)return;let f=managerReportFeeds.get(i);if(f?.loading)return f.promise;if(!force&&f?.lastSuccess&&!isStale(f)&&Date.now()-Date.parse(f.lastSuccess)<REFRESH_MS)return;if(!f){f={data:null,total:null,truncated:false,lastSuccess:null,error:null,loading:false,stale:false};managerReportFeeds.set(i,f)}f.loading=true;if(i===selected)renderMayor();const cityId=managerCityId(i);f.promise=(async()=>{try{if(!/^https?:$/.test(location.protocol))throw Error('Start the live app server to load city reports.');const d=await request('/api/community/reports?'+new URLSearchParams({city:cityId}));if(d.cityId!==cityId||!Array.isArray(d.reports))throw Error('Report service did not return the selected city.');const records=d.reports.filter(r=>r&&r.cityId===cityId&&typeof r.id==='string'&&typeof r.description==='string');f.data=records;f.total=Number.isSafeInteger(d.total)&&d.total>=records.length?d.total:records.length;f.truncated=!!d.truncated;f.lastSuccess=d.fetchedAt||new Date().toISOString();f.error=null;f.stale=false}catch(e){f.error=e.message;f.stale=!!f.data}finally{f.loading=false;if(i===selected)renderMayor()}})();return f.promise}
const retiredImpactNames={wanlaweyn:'Wanlaweyn',eyl:'Eyl',badhan:'Badhan',zeila:'Zeila'},legacyImpactNames={18:'Wanlaweyn',25:'Eyl',27:'Badhan',28:'Zeila'};
