function imageryUrl(i,datetime){const c=cities[i];if(window.MapContext?.buildCopernicusBrowserUrl)return window.MapContext.buildCopernicusBrowserUrl({lat:c[2],lon:c[3],observationDatetime:datetime,zoom:11});const end=new Date(),start=new Date(end.getTime()-14*86400000),u=new URL('https://browser.dataspace.copernicus.eu/');for(const[k,v]of Object.entries({zoom:11,lat:c[2],lng:c[3],themeId:'DEFAULT-THEME',datasetId:'S2_L2A_CDAS',layerId:'1_TRUE_COLOR',fromTime:start.toISOString(),toTime:end.toISOString(),cloudCoverage:100,dateMode:'TIME RANGE',panel:'layers'}))u.searchParams.set(k,v);return u.href}
function renderWatchlist(){const query=$('search').value.trim().toLowerCase();const rows=cities.map((c,i)=>{if(!`${c[0]} ${c[1]}`.toLowerCase().includes(query))return '';const s=summary(i),n=reports.filter(r=>r.cityId===managerCityId(i)).length;return `<tr${i===selected?' class="selected-city"':''}><td><button data-city="${i}"${i===selected?' aria-current="true"':''}>${esc(c[0])}</button><small>${esc(c[1])}</small></td><td>${fmt(s.total)}${s.total===null?'':' mm'}</td><td>${fmt(s.peak)}${s.peak===null?'':' mm'}</td><td><span class="badge ${s.risk.toLowerCase()}">${s.risk}${s.complete&&isStale(feeds.weather)?' · stale':''}</span></td><td>${n?`${n} unverified local report${n>1?'s':''}`:'City impacts unavailable'}</td></tr>`});$('rows').innerHTML=rows.slice(0,15).join('');$('rows-secondary').innerHTML=rows.slice(15,30).join('');const summaries=cities.map((_,i)=>summary(i)),covered=summaries.filter(s=>s.complete).length;$('elevated').textContent=covered?summaries.filter(s=>s.riskWatch).length:'—';$('coverage').textContent=`≥10 mm/day · ${covered}/${cities.length} complete forecasts`;}
